import * as React from 'react';
import { cn } from '@/lib/utils';

export type BottomNavItem = {
  /** Destination URL for the tab. */
  href: string;
  /** Visible tab label. */
  label: string;
  /** Icon shown above the label; always rendered aria-hidden. */
  icon?: React.ReactNode;
  /** Marks the current tab and sets aria-current="page". */
  active?: boolean;
  /** Small count or dot shown in the tab's top corner. */
  badge?: React.ReactNode;
  /** Renders the tab as non-interactive. */
  disabled?: boolean;
};

export type BottomNavProps = React.HTMLAttributes<HTMLElement> & {
  /** Tabs in order. Keep to 3-5 so every target stays thumb-reachable. */
  items: BottomNavItem[];
  /** Router link component (Next Link, react-router Link). */
  linkComponent?: React.ElementType;
  /** Prop used to pass the destination to `linkComponent`. */
  linkHrefProp?: 'href' | 'to';
  /** Landmark label. Default "Primary". */
  label?: string;
  /** Pin the bar to the bottom edge with safe-area padding (default true). */
  fixed?: boolean;
  /** Hide the bar from the md breakpoint up (default true). */
  mobileOnly?: boolean;
};

const tabClass =
  'relative flex min-h-14 w-full flex-col items-center justify-center gap-0.5 px-2 py-2 text-[11px] font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset';

/**
 * Mobile bottom tab bar for the 3-5 primary destinations of an app shell.
 * A nav landmark with aria-current="page" on the active tab, 44px minimum
 * targets, an optional count badge and safe-area padding so the bar clears
 * the iOS home indicator.
 */
export function BottomNav({
  items,
  linkComponent,
  linkHrefProp = 'href',
  label = 'Primary',
  fixed = true,
  mobileOnly = true,
  className,
  ...props
}: BottomNavProps) {
  const LinkEl = linkComponent ?? 'a';
  const destination = (href: string) => (linkHrefProp === 'to' ? { to: href } : { href });

  return (
    <nav
      aria-label={label}
      className={cn(
        'w-full border-t border-border bg-background pb-[env(safe-area-inset-bottom)]',
        fixed && 'fixed inset-x-0 bottom-0 z-40',
        mobileOnly && 'md:hidden',
        className
      )}
      {...props}
    >
      <ul
        className="mx-auto grid w-full max-w-lg"
        style={{ gridTemplateColumns: `repeat(${Math.max(items.length, 1)}, minmax(0, 1fr))` }}
      >
        {items.map((item) => {
          const content = (
            <>
              {item.icon && (
                <span aria-hidden="true" className="[&_svg]:size-5">
                  {item.icon}
                </span>
              )}
              <span>{item.label}</span>
              {item.badge != null && (
                <span className="absolute right-1/4 top-1 rounded-full bg-primary px-1.5 text-[10px] font-semibold leading-4 text-primary-foreground">
                  {item.badge}
                </span>
              )}
            </>
          );

          return (
            <li key={item.href}>
              {item.disabled ? (
                <span
                  aria-disabled="true"
                  className={cn(tabClass, 'text-muted-foreground opacity-50')}
                >
                  {content}
                </span>
              ) : (
                <LinkEl
                  {...destination(item.href)}
                  aria-current={item.active ? 'page' : undefined}
                  className={cn(
                    tabClass,
                    item.active
                      ? 'text-primary'
                      : 'text-muted-foreground hover:text-foreground'
                  )}
                >
                  {content}
                </LinkEl>
              )}
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

{
  "id": "bottom-nav",
  "name": "BottomNav",
  "tier": "organism",
  "description": "Mobile bottom tab bar for the 3-5 primary destinations of an app shell, with an active tab, count badges and safe-area padding.",
  "designIntent": "Mobile apps put primary navigation within thumb reach at the bottom of the screen, but hand-rolled bars drift on target size, active state and the iOS home indicator. BottomNav owns the landmark, the aria-current state, 44px minimum targets and env(safe-area-inset-bottom) so every mobile shell behaves the same.",
  "props": [
    {
      "name": "items",
      "type": "BottomNavItem[]",
      "required": true,
      "description": "Tabs in order: href, label, optional icon, active, badge and disabled."
    },
    {
      "name": "linkComponent",
      "type": "React.ElementType",
      "required": false,
      "description": "Router link component (Next Link, react-router Link)."
    },
    {
      "name": "linkHrefProp",
      "type": "'href' | 'to'",
      "required": false,
      "defaultValue": "href",
      "description": "Prop used to pass the destination to linkComponent.",
      "enum": [
        "href",
        "to"
      ]
    },
    {
      "name": "label",
      "type": "string",
      "required": false,
      "defaultValue": "Primary",
      "description": "Accessible label for the nav landmark."
    },
    {
      "name": "fixed",
      "type": "boolean",
      "required": false,
      "defaultValue": "true",
      "description": "Pin the bar to the bottom edge with safe-area padding."
    },
    {
      "name": "mobileOnly",
      "type": "boolean",
      "required": false,
      "defaultValue": "true",
      "description": "Hide the bar from the md breakpoint up."
    }
  ],
  "examples": [
    {
      "title": "Mobile app shell tabs",
      "code": "<BottomNav\n  items={[\n    { href: '/', label: 'Home', icon: <HomeIcon />, active: true },\n    { href: '/search', label: 'Search', icon: <SearchIcon /> },\n    { href: '/alerts', label: 'Alerts', icon: <BellIcon />, badge: 3 },\n  ]}\n/>",
      "description": "Three primary destinations with one active tab."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't stack more than five tabs",
      "explanation": "Targets stop being thumb-reachable and labels start truncating. Move the extras into a More destination.",
      "example": "// Avoid\n<BottomNav items={eightItems} />\n\n// Prefer 3-5 items plus a More tab"
    },
    {
      "title": "Don't use BottomNav for desktop navigation",
      "explanation": "mobileOnly hides the bar at md and up; desktop keeps SiteHeader/Sidebar.",
      "example": "// Avoid\n<BottomNav items={items} mobileOnly={false} />\n\n// Prefer desktop nav in SiteHeader or Sidebar"
    }
  ],
  "accessibility": [
    {
      "feature": "Navigation landmark",
      "implementation": "Renders <nav> with an accessible name (default \"Primary\")",
      "userRequirements": "Give each bar a distinct label when a page has more than one nav"
    },
    {
      "feature": "Current tab",
      "implementation": "aria-current=\"page\" on the active tab only",
      "userRequirements": "Set active from the router's current location"
    },
    {
      "feature": "Target size",
      "implementation": "Every tab is at least 56px tall with a 44px minimum target",
      "userRequirements": "Keep icons decorative; the label carries the name"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Tab labels",
      "guidelines": [
        "One word where possible",
        "Sentence case",
        "Under 12 characters"
      ],
      "goodExamples": [
        "Home",
        "Search",
        "Alerts"
      ],
      "badExamples": [
        "Go to the alerts page"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "AppShell",
      "relationship": "Pair with AppShell and add bottom padding so content is not hidden behind the bar",
      "example": "<AppShell><main className=\"pb-20\">...</main><BottomNav items={items} /></AppShell>"
    },
    {
      "component": "Badge",
      "relationship": "Counts ride in the item's badge slot; keep them to a single number",
      "example": "<BottomNav items={[{ href: '/alerts', label: 'Alerts', badge: 3 }]} />"
    }
  ],
  "relatedComponents": [
    "AppShell",
    "Sidebar",
    "SiteHeader",
    "Badge"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.8.0",
  "sourceDir": "bottom-nav",
  "exportName": "BottomNav"
}
